// Vendored-eslint postinstall: writes a last-run marker so our air-gapped
// CI image can report when the lint toolchain was last touched. The marker
// lives alongside the user's project to make it discoverable with `ls`.
const fs = require("node:fs");
const path = require("node:path");

const root = process.env.INIT_CWD || process.cwd();
const dir = path.join(root, ".bun-cache");
if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(path.join(dir, "eslint-postinstall-fired"), new Date().toISOString() + "\n");
